124	func newRepoCreateCmd() *cobra.Command {
125		var (
126			projectID    string
127			clusterHost  string
128			objectFormat string
129		)
130		cmd := &cobra.Command{
131			Use:   "create <name>",
132			Short: "Create a repository in a project",
133			Args:  cobra.ExactArgs(1),
134			RunE: func(cmd *cobra.Command, args []string) error {
135				var format coreapi.CreateRepoInputBodyObjectFormat
136				if objectFormat != "" {
137					parsed, err := parseObjectFormat(objectFormat)
138					if err != nil {
139						cmd.SilenceUsage = true
140						return err
141					}
142					format = parsed
143				}
144				return runCoreMutation(cmd, func(ctx context.Context, c *coreapi.Client) (string, any, error) {
145					projID, err := resolveProjectRef(ctx, c, projectID)
146					if err != nil {
147						return "", nil, err
148					}
149					body := &coreapi.CreateRepoInputBody{
150						Name:      args[0],
151						ProjectId: projID,
152					}
153					if clusterHost != "" {
154						body.ClusterHost = coreapi.NewOptString(clusterHost)
155					}
156					if format != "" {
157						body.ObjectFormat = coreapi.NewOptCreateRepoInputBodyObjectFormat(format)
158					}
159					created, err := c.CreateRepo(ctx, body)
160					if err != nil {
161						return "", nil, err
162					}
163					wire, err := repoCreateOutput(created)
164					if err != nil {
165						return "", nil, err
166					}
167					msg := fmt.Sprintf("✓ Created repository %s (%s)", created.Name, created.ID)
